'use strict';
const fs=require('fs'),{performance}=require('perf_hooks'),crypto=require('crypto');
const [root,inputPath,mode,reportPath]=process.argv.slice(2);
const inputBytes=fs.readFileSync(inputPath),input=JSON.parse(inputBytes);
input.sourceCoverage=input.coverage;delete input.coverage;
const {BUILD_ID}=require(root+'/src/artifact');
const start=performance.now();
(async()=>{try {
const r=mode==='worker'?(await require(root+'/src/shared-scans').analyzeShared(input)).evidence:require(root+'/src/auditor').auditEvidence(input);
fs.writeFileSync(reportPath,JSON.stringify(r));
console.log(JSON.stringify({package:input.packageName,mode,buildId:BUILD_ID,inputSha256:crypto.createHash('sha256').update(inputBytes).digest('hex'),ms:performance.now()-start,verdict:r.verdict,findings:r.findings.length,counts:r.findings.reduce((a,f)=>(a[f.category]=(a[f.category]||0)+1,a),{}),rss:process.memoryUsage().rss,reportSha256:crypto.createHash('sha256').update(JSON.stringify(r)).digest('hex')}));
}catch(e){console.log(JSON.stringify({package:input.packageName,mode,buildId:BUILD_ID,ms:performance.now()-start,error:e.code||e.name,message:e.message}));process.exitCode=1;}})();
